const e = $input.first().json;
const wf = e.workflow || {};
// n8n sends `execution` for a failure inside a run, but `trigger`
// when the failing node is the trigger itself (a poll that could not
// reach its API). Reading only `execution` produced alerts that said
// 'failed at <blank>: unknown error'.
const ctx = e.execution || e.trigger || {};
const err = ctx.error || e.error || {};
const message = err.message || err.description || err.reason
  || (Object.keys(err).length ? JSON.stringify(err).slice(0, 300) : '')
  || 'unknown error';
const node = ctx.lastNodeExecuted || (err.node && err.node.name) || '';

// Transient connectivity faults are expected when this host sleeps or
// loses its network; the next poll recovers on its own. They are still
// logged, but they do not warrant waking the operator.
const TRANSIENT = [
  'connection to the server was closed',
  'socket hang up', 'ECONNRESET', 'ETIMEDOUT', 'ENOTFOUND',
  'EAI_AGAIN', 'network socket disconnected', 'getaddrinfo',
];
const lower = String(message).toLowerCase();
const transient = TRANSIENT.some(t => lower.includes(t.toLowerCase()));

return [{ json: {
  Timestamp: new Date().toISOString(),
  User: 'system',
  Intent: transient ? 'error_transient' : 'error',
  Input: wf.name || 'unknown workflow',
  Output: node,
  MessageId: 'err-' + (ctx.id || Date.now()),
  Error: message,
  Url: ctx.url || '',
  transient,
} }];
